import sys

def solve():
	inp = sys.stdin.readline
	n = int(inp())
	a = list(map(int, inp().split()))
	b = list(map(int, inp().split()))
	w = [0] * (n + 1)
	j = 0
	for i in range(n):
		x = b[i]
		while j < n and a[j] != x:
			w[a[j]] += 1
			j += 1
		if j == n:
			print('NO')
			return
		if i + 1 < n and b[i + 1] == x:
			if j + 1 >= n or a[j + 1] != x:
				if w[x] > 0:
					w[x] -= 1
					i += 1
					continue
		j += 1
	print('YES')

def main():
	for i in range(int(sys.stdin.readline())):
		solve()
main()
